def compute(vars):
    cash_paid = vars["v1"]
    purchase_price = vars["v2"]
    if purchase_price == 0:
        return None
    portion = cash_paid / purchase_price
    return {
        "value": portion,
        "trace": {
            "cash_paid": cash_paid,
            "aggregate_purchase_price": purchase_price,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
